'use strict'

/**
 * specs-filter-ui.js
 * 
 * Renders a filter/sort UI on the homepage that allows users to dynamically
 * filter and sort all specs (ratified + under-development). Fetches data from
 * specs-data.json generated by the Antora extension.
 * 
 * Default view shows static twisties. When any filter is applied, switches to
 * a dynamic filtered grid. Reset clears filters and returns to default view.
 */

document.addEventListener('DOMContentLoaded', async function() {
  const filterContainer = document.querySelector('#specs-filter-container')
  if (!filterContainer) return

  try {
    // Fetch specs data
    // The file is at build/reference/specs-data.json
    // The homepage is at build/reference/home/index.html
    // So from homepage, the relative path is ../specs-data.json
    const response = await fetch('../specs-data.json')
    if (!response.ok) throw new Error(`Failed to fetch specs-data.json: ${response.status}`)
    const { specs } = await response.json()

    // Extract unique groups and statuses
    const groups = [...new Set(specs.map(s => s.group))].sort()
    const statuses = [...new Set(specs.map(s => s.status))].sort()

    // Build UI
    renderFilterUI(filterContainer, specs, groups, statuses)
  } catch (err) {
    console.error('[specs-filter-ui] Error:', err)
    filterContainer.innerHTML = '<p style="color: red;">Error loading filters. Please refresh the page.</p>'
  }
})

function renderFilterUI(container, specs, groups, statuses) {
  const state = {
    specs,
    groups,
    statuses,
    filters: {
      group: null,
      status: null,
      search: '',
    },
    sortBy: 'title',
    hasActiveFilters: false,
  }

  const ui = document.createElement('div')
  ui.className = 'specs-filter-panel'
  ui.innerHTML = `
    <div class="specs-filter-controls">
      <div class="filter-group">
        <label for="group-select">Group:</label>
        <select id="group-select" class="filter-select">
          <option value="">All Groups</option>
          ${groups.map(g => `<option value="${g}">${formatGroupName(g)}</option>`).join('')}
        </select>
      </div>

      <div class="filter-group">
        <label for="status-select">Status:</label>
        <select id="status-select" class="filter-select">
          <option value="">All Statuses</option>
          ${statuses.map(s => `<option value="${s}">${formatStatus(s)}</option>`).join('')}
        </select>
      </div>

      <div class="filter-group">
        <label for="sort-select">Sort by:</label>
        <select id="sort-select" class="filter-select">
          <option value="title">Title (A-Z)</option>
          <option value="releaseDate">Release Date</option>
          <option value="status">Status</option>
        </select>
      </div>

      <div class="filter-group">
        <label for="search-input">Search:</label>
        <input 
          type="text" 
          id="search-input" 
          class="filter-input" 
          placeholder="Spec title..."
          autocomplete="off"
        />
      </div>

      <button id="reset-filters-btn" class="btn-reset" style="display: none;">
        Clear Filters
      </button>
    </div>

    <div id="filtered-results" style="display: none;">
      <div class="card-grid card-grid-3"></div>
    </div>
  `

  container.appendChild(ui)

  // Get DOM elements
  const groupSelect = ui.querySelector('#group-select')
  const statusSelect = ui.querySelector('#status-select')
  const sortSelect = ui.querySelector('#sort-select')
  const searchInput = ui.querySelector('#search-input')
  const resetBtn = ui.querySelector('#reset-filters-btn')
  const filteredResults = ui.querySelector('#filtered-results')
  const controlsPanel = ui.querySelector('.specs-filter-controls')
  const defaultView = container.querySelector('.default-specs-view')

  // Event handlers
  function updateFilters() {
    state.filters.group = groupSelect.value
    state.filters.status = statusSelect.value
    state.filters.search = searchInput.value.toLowerCase()
    state.sortBy = sortSelect.value

    state.hasActiveFilters = Boolean(
      state.filters.group || state.filters.status || state.filters.search
    )

    if (state.hasActiveFilters) {
      renderFilteredSpecs(state, filteredResults, controlsPanel, defaultView, resetBtn)
    } else {
      // Return to default view
      filteredResults.style.display = 'none'
      if (defaultView) defaultView.style.display = 'block'
      resetBtn.style.display = 'none'
    }
  }

  groupSelect.addEventListener('change', updateFilters)
  statusSelect.addEventListener('change', updateFilters)
  sortSelect.addEventListener('change', updateFilters)
  searchInput.addEventListener('input', updateFilters)

  resetBtn.addEventListener('click', function() {
    groupSelect.value = ''
    statusSelect.value = ''
    searchInput.value = ''
    sortSelect.value = 'title'
    updateFilters()
  })
}

function renderFilteredSpecs(state, container, controlsPanel, defaultView, resetBtn) {
  // Filter specs
  let filtered = state.specs.filter(spec => {
    if (state.filters.group && spec.group !== state.filters.group) return false
    if (state.filters.status && spec.status !== state.filters.status) return false
    if (state.filters.search && !spec.title.toLowerCase().includes(state.filters.search)) {
      return false
    }
    return true
  })

  // Sort
  if (state.sortBy === 'title') {
    filtered.sort((a, b) => a.title.localeCompare(b.title))
  } else if (state.sortBy === 'releaseDate') {
    filtered.sort((a, b) => {
      if (!a.releaseDate) return 1
      if (!b.releaseDate) return -1
      return b.releaseDate.localeCompare(a.releaseDate)
    })
  } else if (state.sortBy === 'status') {
    const statusOrder = { draft: 0, review: 1, freeze: 2, 'ratification-ready': 3 }
    filtered.sort((a, b) => {
      const orderA = statusOrder[a.status?.toLowerCase()] ?? 999
      const orderB = statusOrder[b.status?.toLowerCase()] ?? 999
      return orderA - orderB || a.title.localeCompare(b.title)
    })
  }

  // Hide default view
  if (defaultView) defaultView.style.display = 'none'

  // Render cards
  const gridContainer = container.querySelector('.card-grid')
  gridContainer.innerHTML = filtered.length > 0
    ? filtered.map(spec => buildSpecCard(spec)).join('')
    : '<div class="no-results"><p>No specifications match your filters.</p></div>'

  container.style.display = 'block'
  resetBtn.style.display = 'inline-block'
}

function buildSpecCard(spec) {
  const htmlHref = spec.htmlPath || `../${spec.name}/index.html`
  const pdfUrl = spec.pdfUrl || '#'
  const pdfClass = spec.pdfUrl ? 'card-more-link' : 'card-more-link disabled'
  const pdfAttrs = spec.pdfUrl ? 'target="_blank" rel="noopener noreferrer"' : ''

  return `
    <div class="card card--spec-result">
      <div class="card-header">
        <h3 class="card-title"><a href="${escapeHtml(htmlHref)}">${escapeHtml(spec.title)}</a></h3>
      </div>
      <div class="card-body">
        <p class="card-description">${escapeHtml(spec.description || '')}</p>
        <div class="card-meta">
          <span class="meta-group">${escapeHtml(formatGroupName(spec.group))}</span>
          <span class="meta-status">${escapeHtml(formatStatus(spec.status))}</span>
          ${spec.releaseDate ? `<span class="meta-date">${escapeHtml(spec.releaseDate)}</span>` : ''}
        </div>
      </div>
      <div class="card-footer">
        <a href="${escapeHtml(htmlHref)}" class="card-more-link">View Spec</a>
        ${spec.detailsUrl ? `<a href="${escapeHtml(spec.detailsUrl)}" class="card-more-link" target="_blank" rel="noopener noreferrer">Details</a>` : ''}
        <a href="${escapeHtml(pdfUrl)}" class="${pdfClass}" ${pdfAttrs}>PDF</a>
      </div>
    </div>
  `
}

function formatGroupName(group) {
  const names = {
    'isa': 'ISA',
    'platform-software': 'Platform Software',
    'hardware': 'Hardware',
    'debug-trace-ras': 'Debug, Trace, and RAS',
    'profile': 'Profiles',
    'profiles': 'Profiles',
    'platforms': 'Platforms',
    'application-software': 'Application Enablement',
    'under-development': 'Under Development',
  }
  return names[group] || group.split('-').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ')
}

function formatStatus(status) {
  if (!status) return ''
  return status.split('-').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ')
}

function escapeHtml(str) {
  if (!str) return ''
  const div = document.createElement('div')
  div.textContent = str
  return div.innerHTML
}
